+// sessionTranscriptName is a session's full.jsonl relative to the .entire root.
+func sessionTranscriptName(sessionID string) string {
+	return entiredir.MustName(paths.SessionMetadataDirFromSessionID(sessionID)) + "/" + paths.TranscriptFileName
+}
+
+// clearFilesystemTranscript removes the staged full.jsonl for a session, and is
+// called from the same place (and under the same guard) as
+// clearFilesystemPrompt: the session's work has been condensed into a
+// checkpoint and no carry-forward files remain.
+//
+// The on-disk transcript is a staging buffer, not a store. It is rewritten
+// WHOLESALE from the agent's own transcript on every Stop (see the copy_transcript
+// span in lifecycle.go), and the only readers are the two tree-building walks
+// that run before this point — addDirectoryToChanges (shadow) and
+// copyEntireMetadataDir (v1). Every other reader of a session's transcript goes
+// through a git tree, not this file. So removing it costs a continuing session
+// nothing: the next Stop recreates it.
+//
+// Without this, nothing ever removed it. A session's transcript stayed in the
+// worktree permanently after its content was already committed and pushed,
+// growing to hundreds of MB across a few hundred sessions.
+//
+// The incremental redaction cache is unaffected: it lives in the git common dir
+// and is keyed by prefix content hash, not by this path's existence, so the next
+// Stop still redacts incrementally rather than from scratch.
+func clearFilesystemTranscript(ctx context.Context, sessionID string) {
+	root, err := entiredir.OpenForRead(ctx)
+	if err != nil {
+		return
+	}
+	// Both spellings: a session captured by an older CLI wrote full.log.
+	_ = osroot.RemoveNoSymlinks(root, sessionTranscriptName(sessionID)) //nolint:errcheck // best-effort; the next Stop rewrites it
+	legacy := entiredir.MustName(paths.SessionMetadataDirFromSessionID(sessionID)) + "/" + paths.TranscriptFileNameLegacy
+	_ = osroot.RemoveNoSymlinks(root, legacy) //nolint:errcheck // best-effort; absent on every session this CLI captured
+}
